/**
 * Orgs the user still holds a live membership in. A closed workspace is
 * omitted entirely — it is gone from every member's list.
 */
export async function listOrgsForUser(
  userId: UserId,
): Promise<readonly Organization[]> {
  const rows = getDb()
    .select({ org: organizations })
    .from(members)
    .innerJoin(organizations, eq(organizations.id, members.orgId))
    .where(
      and(
        eq(members.userId, userId),
        isNull(members.archivedAt),
        isNull(organizations.archivedAt),
      ),
    )
    .all();

  return rows.map((row) => toOrganization(row.org));
}

/**
 * Refuses work against a workspace that has been closed. A missing row is
 * left to the caller's own not-found handling.
 */
export async function assertOrganizationOpen(orgId: OrgId): Promise<void> {
  const org = await findOrgById(orgId);
  if (org !== null && isArchived(org)) {
    throw new AlreadyArchivedError("Organization", orgId);
  }
}

/**
 * Drops every delivery still waiting for an organization. Used when the
 * workspace is closed so a queued payload cannot go out afterwards.
 */
export async function failPendingDeliveries(
  orgId: OrgId,
  error: string,
): Promise<number> {
  const rows = getDb()
    .update(webhookDeliveries)
    .set({
      status: "failed",
      lastError: error.slice(0, 500),
      updatedAt: toIsoTimestamp(new Date()),
    })
    .where(
      and(
        orgPredicate(webhookDeliveries.orgId, orgId),
        eq(webhookDeliveries.status, "pending"),
      ),
    )
    .returning({ id: webhookDeliveries.id })
    .all();
  return rows.length;
}

